    out.prereqTechResearchCost = static_cast<i32>(unitEntry.GetPrereqAndTech() != NO_TECH && GC.GetGameTechs()->GetEntry(static_cast<TechTypes>(unitEntry.GetPrereqAndTech())) ? GC.GetGameTechs()->GetEntry(static_cast<TechTypes>(unitEntry.GetPrereqAndTech()))->GetResearchCost() : 0);
    // Reduced max-over-yields form of the per-yield native array; the facade answers any yield index with the captured maximum.
    {
        i32 clampedYieldFromKills = static_cast<i32>(VoxRlMaxUnitEntryYieldFromKills(unitEntry, false));
        if (clampedYieldFromKills < -32768) clampedYieldFromKills = -32768;
        if (clampedYieldFromKills > 32767) clampedYieldFromKills = 32767;
        out.yieldFromKills = static_cast<i16>(clampedYieldFromKills);
    }
    // Reduced max-over-yields form of the per-yield native array; the facade answers any yield index with the captured maximum.
    {
        i32 clampedYieldFromBarbarianKills = static_cast<i32>(VoxRlMaxUnitEntryYieldFromKills(unitEntry, true));
        if (clampedYieldFromBarbarianKills < -32768) clampedYieldFromBarbarianKills = -32768;
        if (clampedYieldFromBarbarianKills > 32767) clampedYieldFromBarbarianKills = 32767;
        out.yieldFromBarbarianKills = static_cast<i16>(clampedYieldFromBarbarianKills);
    }
    // Captured from the native getter.
    out.requiresFaithPurchaseEnabled = (unitEntry.IsRequiresFaithPurchaseEnabled()) ? 1 : 0;
